-- =====================================================================
--  SPM · Controle de Estoque v3 — ETAPA 2: MIGRAÇÃO DOS DADOS
-- ---------------------------------------------------------------------
--  Origem: planilha "SPM - Controle de Estoque v2" (export de 23/10/2026,
--  última movimentação: 23/10/2026 10:23).
--
--  Onde rodar: Supabase > "SPM Logística" > SQL Editor > New query.
--  Cole o arquivo INTEIRO e clique em "Run". Rode uma única vez.
--
--  O QUE ESTE SCRIPT FAZ (e o porquê):
--
--  1. 56 itens ativos com o ESTOQUE ATUAL EXATAMENTE COMO NA PLANILHA.
--     O estoque NÃO é recalculado pelo histórico: em 24 itens o
--     histórico não fecha com o estoque, e recalcular mudaria números
--     reais (ex.: Lápis cairia de 122 para 1). Essas 24 diferenças vão
--     aparecer na aba "Atenção" para o Almino resolver por contagem.
--
--  2. 9 itens que tinham sido apagados da planilha, mas ainda têm
--     movimentações (5× "Livro de ata", Detergente, Inseticida, Ácido
--     muriático, Balde). Entram ARQUIVADOS e com estoque 0, só para o
--     histórico continuar apontando para algo. Não aparecem na lista.
--
--  3. As 350 movimentações, com IDs, datas e horários originais,
--     marcadas como origem = 'migracao'. Ajustes de padronização:
--       - espaços repetidos nos nomes viram um só ("Açúcar  Cristal"
--         passa a "Açúcar Cristal"), para a busca funcionar;
--       - "Feito por" com o e-mail franciscoalmino731@gmail.com vira
--         "Almino" (mesma pessoa, que nos registros recentes já aparece
--         assim). Os demais valores ficam como estavam.
--     Os horários estão no fuso de Fortaleza (-03), o mesmo da planilha.
--
--  SEGURANÇA DO PROCESSO:
--     - Tudo roda dentro de uma transação: se qualquer linha falhar,
--       NADA é gravado e o banco fica como estava.
--     - Se o banco já tiver itens, o script para logo no início, sem
--       gravar nada (proteção contra rodar duas vezes).
-- =====================================================================

begin;

do $$
begin
  if exists (select 1 from public.itens) or exists (select 1 from public.movimentacoes) then
    raise exception 'O banco já tem dados. Migração cancelada para não duplicar nada.';
  end if;
end;
$$;

-- itens ativos (estoque atual exatamente como na planilha)

-- itens que foram apagados da planilha mas têm movimentações: entram ARQUIVADOS, com estoque 0

-- movimentações (todas as 350, na ordem original)

commit;


-- =====================================================================
-- CONFERÊNCIA (aparece na aba "Results")
-- ---------------------------------------------------------------------
-- Esperado:
--   itens_ativos = 56 · itens_arquivados = 9 · movimentacoes = 350
--   estoque_total = 868 (soma da coluna "Estoque Atual" da planilha)
--   primeira = 04/08/2026 08:21 · ultima = 23/10/2026 10:23
--   divergencias = 24 · possiveis_duplicadas = 7
--   (são as pendências que a aba "Atenção" vai listar)
-- =====================================================================
select
  (select count(*) from public.itens where ativo)        as itens_ativos,
  (select count(*) from public.itens where not ativo)    as itens_arquivados,
  (select count(*) from public.movimentacoes)            as movimentacoes,
  (select trim_scale(sum(estoque_atual)) from public.itens) as estoque_total,
  (select to_char(min(data_hora) at time zone 'America/Fortaleza', 'DD/MM/YYYY HH24:MI') from public.movimentacoes) as primeira,
  (select to_char(max(data_hora) at time zone 'America/Fortaleza', 'DD/MM/YYYY HH24:MI') from public.movimentacoes) as ultima,
  (select count(*) from public.v_divergencias)           as divergencias,
  (select count(*) from public.v_possiveis_duplicadas)   as possiveis_duplicadas;
